{"path": "version-sentry.py", "content": "#!/usr/bin/env python3
"""
Version Sentry — 版本哨兵
===========================================================
跨设备应用/依赖/容器版本更新跟踪与决策工具

用法:
  python version-sentry.py init                          # 初始化配置
  python version-sentry.py scan deps     [--dir ...]     # 扫描项目依赖
  python version-sentry.py scan devices                  # 扫描 SSH 设备软件
  python version-sentry.py scan docker                   # 扫描 Docker 镜像
  python version-sentry.py scan all                      # 执行全部扫描
  python version-sentry.py add device   [args]           # 添加设备
  python version-sentry.py add project  [args]           # 添加项目
  python version-sentry.py add app      [args]           # 手动录入设备 App
  python version-sentry.py report       [--open]         # 生成 HTML 报告
  python version-sentry.py history      [--days N]       # 查看版本变更历史
  python version-sentry.py list                          # 列出所有已注册项

依赖: Python 3.8+ (标准库即可, SSH 需 paramiko)
  pip install paramiko    # SSH 远程扫描 (可选)
  pip install pyyaml      # YAML 配置 (推荐)
===========================================================
"""

from __future__ import annotations

import argparse
import csv
import dataclasses
import datetime
import html
import json
import os
import re
import sqlite3
import subprocess
import sys
import textwrap
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass, field, asdict
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

# ── 常量 ──────────────────────────────────────────────────────────

VERSION = "0.2.0"
CONFIG_DIR = Path.home() / ".version-sentry"
CONFIG_FILE = CONFIG_DIR / "config.json"
DB_FILE = CONFIG_DIR / "versions.db"
REPORT_DIR = CONFIG_DIR / "reports"

DEFAULT_CONFIG = {
    "devices": [],
    "projects": [],
    "manual_apps": {},
    "docker": {"hosts": ["local"]},
    "notify": {"email": None, "webhook": None},
}

# ── 数据模型 ──────────────────────────────────────────────────────

@dataclass
class Device:
    name: str
    type: str              # "ssh" | "local" | "manual"
    host: str = ""
    port: int = 22
    user: str = ""
    os_type: str = ""      # "linux" | "windows" | "macos"
    notes: str = ""

@dataclass
class Project:
    name: str
    path: str
    pkg_managers: List[str] = field(default_factory=list)  # ["npm","pip","cargo","go","mixed"]
    notes: str = ""

@dataclass
class VersionRecord:
    source: str        # 来源标识, 如 device/project/docker 名称
    category: str      # "dependency" | "app" | "docker" | "system"
    item_name: str     # 包名/应用名/镜像名
    current_version: str
    latest_version: str = ""
    status: str = "unknown"   # "latest" | "outdated" | "unknown" | "error"
    scanned_at: str = ""
    extra: str = ""

# ── 配置管理 ──────────────────────────────────────────────────────

def load_config() -> dict:
    if not CONFIG_FILE.exists():
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        save_config(DEFAULT_CONFIG)
        return dict(DEFAULT_CONFIG)
    raw = CONFIG_FILE.read_text(encoding="utf-8")
    if CONFIG_FILE.suffix == ".json" or True:
        return json.loads(raw)
    try:
        import yaml
        return yaml.safe_load(raw)
    except ImportError:
        return json.loads(raw)

def save_config(cfg: dict):
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    CONFIG_FILE.write_text(
        json.dumps(cfg, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )

def get_db() -> sqlite3.Connection:
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(str(DB_FILE))
    db.execute("""
        CREATE TABLE IF NOT EXISTS version_history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            source TEXT NOT NULL,
            category TEXT NOT NULL,
            item_name TEXT NOT NULL,
            current_version TEXT NOT NULL,
            latest_version TEXT DEFAULT '',
            status TEXT DEFAULT 'unknown',
            scanned_at TEXT NOT NULL,
            extra TEXT DEFAULT ''
        )
    """)
    db.execute("""
        CREATE INDEX IF NOT EXISTS idx_history_scanned
        ON version_history(scanned_at)
    """)
    db.commit()
    return db

def save_records(db: sqlite3.Connection, records: List[VersionRecord]):
    now = datetime.datetime.now().isoformat(timespec="seconds")
    for r in records:
        db.execute(
            "INSERT INTO version_history (source, category, item_name, current_version, latest_version, status, scanned_at, extra) VALUES (?,?,?,?,?,?,?,?)",
            (r.source, r.category, r.item_name, r.current_version, r.latest_version, r.status, now, r.extra),
        )
    db.commit()

# ── 工具函数 ──────────────────────────────────────────────────────

def fetch_json(url: str, timeout: int = 15) -> Optional[dict]:
    """GET 一个 JSON 接口, 容错返回 None"""
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "version-sentry/0.2"})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except Exception as e:
        return None

def semver_key(v: str) -> tuple:
    """把 '1.2.3' 转成可排序元组 (1,2,3)，非 semver 就变 (0,)"""
    parts = re.findall(r"\d+", v)
    if parts:
        return tuple(int(p) for p in parts)
    return (0,)

def compare_versions(current: str, latest: str) -> str:
    if not latest or not current:
        return "unknown"
    if current.strip().lower() == latest.strip().lower():
        return "latest"
    try:
        if semver_key(latest) > semver_key(current):
            return "outdated"
        return "latest"
    except:
        return "unknown"

def run_cmd(cmd: List[str], timeout: int = 30) -> Tuple[int, str]:
    """运行本地命令, 返回 (returncode, stdout+stderr)"""
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return r.returncode, (r.stdout or "") + (r.stderr or "")
    except FileNotFoundError:
        return -1, f"命令未找到: {cmd[0]}"
    except subprocess.TimeoutExpired:
        return -1, f"命令超时 ({timeout}s): {' '.join(cmd)}"

# ══════════════════════════════════════════════════════════════════
#  模块一: 项目依赖扫描
# ══════════════════════════════════════════════════════════════════

def scan_project_deps(project: Project) -> List[VersionRecord]:
    """扫描单个项目的所有依赖管理器"""
    records: List[VersionRecord] = []
    proj_path = Path(project.path).expanduser().resolve()

    if not proj_path.is_dir():
        print(f"  ⚠  项目路径不存在: {proj_path}")
        return records

    managers = project.pkg_managers or detect_pkg_managers(proj_path)

    if "npm" in managers or "mixed" in managers:
        records += scan_npm(project.name, proj_path)
    if "pip" in managers or "mixed" in managers:
        records += scan_pip(project.name, proj_path)
    if "cargo" in managers or "mixed" in managers:
        records += scan_cargo(project.name, proj_path)
    if "go" in managers or "mixed" in managers:
        records += scan_go(project.name, proj_path)

    return records

def detect_pkg_managers(path: Path) -> List[str]:
    mgrs = []
    if (path / "package.json").exists():
        mgrs.append("npm")
    if (path / "requirements.txt").exists() or (path / "pyproject.toml").exists():
        mgrs.append("pip")
    if (path / "Cargo.toml").exists():
        mgrs.append("cargo")
    if (path / "go.mod").exists():
        mgrs.append("go")
    return mgrs or ["mixed"]

# ─ npm ─

def scan_npm(source: str, path: Path) -> List[VersionRecord]:
    records: List[VersionRecord] = []
    pkg_json = path / "package.json"
    if not pkg_json.exists():
        return records
    try:
        data = json.loads(pkg_json.read_text(encoding="utf-8"))
    except:
        return records

    deps = {}
    deps.update(data.get("dependencies", {}))
    deps.update(data.get("devDependencies", {}))

    if not deps:
        return records

    print(f"  📦 npm: 发现 {len(deps)} 个依赖, 正在查询最新版本...")
    # 批量查询（逐个查，容错）
    checked = 0
    for pkg, ver in deps.items():
        current = ver.lstrip("^~>=<")
        rec = VersionRecord(
            source=source,
            category="dependency",
            item_name=f"npm:{pkg}",
            current_version=current,
        )
        # 查 npm registry
        url = f"https://registry.npmjs.org/{urllib.parse.quote(pkg, safe='')}/latest"
        data = fetch_json(url)
        if data and "version" in data:
            rec.latest_version = data["version"]
            rec.status = compare_versions(current, data["version"])
        else:
            rec.status = "unknown"
        records.append(rec)
        checked += 1
        if checked % 20 == 0:
            print(f"    ...已查 {checked}/{len(deps)}")

    return records

# ─ pip ─

def scan_pip(source: str, path: Path) -> List[VersionRecord]:
    records: List[VersionRecord] = []
    req_file = path / "requirements.txt"
    pyproj = path / "pyproject.toml"

    pkgs: Dict[str, str] = {}

    if req_file.exists():
        for line in req_file.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#") or line.startswith("-"):
                continue
            m = re.match(r"([a-zA-Z0-9_.-]+)\s*([><=!~]+\s*[\d.*]+)?", line)
            if m:
                pkgs[m.group(1).lower()] = (m.group(2) or "").lstrip("=~><")

    if pyproj.exists():
        # 极简解析 (主流 pyproject.toml 格式)
        text = pyproj.read_text(encoding="utf-8")
        # 找 [project] 下的 dependencies
        in_project = False
        for line in text.splitlines():
            if line.strip().startswith("[project"):
                in_project = True
                continue
            if in_project and line.strip().startswith("["):
                in_project = False
            if in_project and "=" in line and "dependencies" in line:
                continue
            if in_project and line.strip().startswith('"') or line.strip().startswith("'"):
                m = re.match(r"""['\"]([a-zA-Z0-9_.-]+)([><=!~][\d.*]+)?['\"]""", line.strip().strip(","))
                if m and m.group(1):
                    pkgs[m.group(1).lower()] = (m.group(2) or "").lstrip("=~><")

    if not pkgs:
        return records

    print(f"  🐍 pip: 发现 {len(pkgs)} 个依赖, 正在查询 PyPI...")
    for pkg, ver in pkgs.items():
        rec = VersionRecord(
            source=source,
            category="dependency",
            item_name=f"pip:{pkg}",
            current_version=ver or "?",
        )
        url = f"https://pypi.org/pypi/{urllib.parse.quote(pkg, safe='')}/json"
        data = fetch_json(url)
        if data and "info" in data and "version" in data["info"]:
            rec.latest_version = data["info"]["version"]
            rec.status = compare_versions(ver, data["info"]["version"])
        records.append(rec)

    return records

# ─ cargo ─

def scan_cargo(source: str, path: Path) -> List[VersionRecord]:
    records: List[VersionRecord] = []
    cargo = path / "Cargo.toml"
    if not cargo.exists():
        return records

    text = cargo.read_text(encoding="utf-8")
    deps: Dict[str, str] = {}
    in_deps = False
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.startswith("[dependencies"):
            in_deps = True
            continue
        if in_deps and stripped.startswith("["):
            in_deps = False
        if in_deps and "=" in stripped and not stripped.startswith("#"):
            parts = stripped.split("=", 1)
            name = parts[0].strip()
            ver = parts[1].strip().strip('"').strip("'").strip()
            if name and ver and not ver.startswith("{") and not ver.startswith("git"):
                deps[name] = ver

    if not deps:
        return records

    print(f"  🦀 cargo: 发现 {len(deps)} 个依赖, 正在查询 crates.io...")
    for pkg, ver in deps.items():
        rec = VersionRecord(
            source=source,
            category="dependency",
            item_name=f"cargo:{pkg}",
            current_version=ver,
        )
        url = f"https://crates.io/api/v1/crates/{urllib.parse.quote(pkg, safe='')}"
        data = fetch_json(url)
        if data and "crate" in data and "max_version" in data["crate"]:
            rec.latest_version = data["crate"]["max_version"]
            rec.status = compare_versions(ver, data["crate"]["max_version"])
        records.append(rec)

    return records

# ─ go ─

def scan_go(source: str, path: Path) -> List[VersionRecord]:
    records: List[VersionRecord] = []
    gomod = path / "go.mod"
    if not gomod.exists():
        return records

    text = gomod.read_text(encoding="utf-8")
    deps: Dict[str, str] = {}
    for line in text.splitlines():
        stripped = line.strip()
        # require (
        #   pkg v1.2.3
        # )
        if stripped.startswith("require") or stripped.startswith(")"):
            continue
        m = re.match(r"([a-zA-Z0-9_./-]+)\s+v?([\d.]+)", stripped)
        if m:
            deps[m.group(1)] = m.group(2)

    if not deps:
        return records

    print(f"  🐹 go: 发现 {len(deps)} 个依赖, 正在查询 proxy.golang.org...")
    for pkg, ver in deps.items():
        rec = VersionRecord(
            source=source,
            category="dependency",
            item_name=f"go:{pkg}",
            current_version=ver,
        )
        # Go proxy 返回格式: v1.2.3
        url = f"https://proxy.golang.org/{urllib.parse.quote(pkg, safe='')}/@latest"
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "version-sentry/0.2"})
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                if "Version" in data:
                    rec.latest_version = data["Version"].lstrip("v")
                    rec.status = compare_versions(ver, rec.latest_version)
        except:
            pass
        records.append(rec)

    return records


