#  模块二: SSH 远程设备扫描
# ══════════════════════════════════════════════════════════════════

def scan_ssh_device(device: Device) -> List[VersionRecord]:
    """通过 SSH 连接到远程设备, 收集已安装软件版本"""
    records: List[VersionRecord] = []
    print(f"  🔌 正在连接 {device.name} ({device.host})...")

    # 检查 paramiko 是否可用
    try:
        import paramiko
    except ImportError:
        print(f"    ⚠  paramiko 未安装, 跳过 SSH 扫描")
        print(f"    💡 pip install paramiko")
        return records

    client = paramiko.SSHClient()
    client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    try:
        client.connect(
            hostname=device.host,
            port=device.port or 22,
            username=device.user,
            timeout=10,
        )
    except Exception as e:
        print(f"    ❌ 连接失败: {e}")
        client.close()
        return [VersionRecord(
            source=device.name, category="system",
            item_name="__connection__",
            current_version="", latest_version="",
            status="error", extra=str(e),
        )]

    commands = {
        "linux": [
            ("dpkg -l", "linux_deb"),
            ("pip3 list --format=columns 2>/dev/null || pip list --format=columns 2>/dev/null", "pip"),
            ("npm list -g --depth=0 2>/dev/null", "npm_global"),
            ("flatpak list --app 2>/dev/null", "flatpak"),
            ("snap list 2>/dev/null", "snap"),
            ("uname -a", "kernel"),
        ],
        "macos": [
            ("brew list --versions 2>/dev/null", "brew"),
            ("system_profiler SPApplicationsDataType 2>/dev/null | head -200", "mac_apps"),
            ("sw_vers", "macos_version"),
            ("pip3 list --format=columns 2>/dev/null", "pip"),
        ],
        "windows": [
            ("powershell -Command \"Get-ItemProperty HKLM:\\Software\\Wow6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\* | Select-Object DisplayName, DisplayVersion | ConvertTo-Json\" 2>$null", "win_apps"),
            ("powershell -Command \"winget list 2>$null\"", "winget"),
            ("powershell -Command \"choco list --local-only 2>$null\"", "choco"),
        ],
    }

    os_type = device.os_type or "linux"
    cmds = commands.get(os_type, commands["linux"])

    for cmd, source_tag in cmds:
        try:
            stdin, stdout, stderr = client.exec_command(cmd, timeout=30)
            out = stdout.read().decode("utf-8", errors="replace").strip()
            if not out:
                continue
        except Exception as e:
            continue

        # 解析输出
        if source_tag == "linux_deb":
            for line in out.splitlines():
                if line.startswith("ii "):
                    parts = line.split()
                    if len(parts) >= 3:
                        pkg_name = parts[1]
                        pkg_ver = parts[2]
                        records.append(VersionRecord(
                            source=device.name, category="system",
                            item_name=pkg_name, current_version=pkg_ver,
                        ))
        elif source_tag == "brew":
            for line in out.splitlines():
                m = re.match(r"(\S+)\s+(.+)", line)
                if m:
                    records.append(VersionRecord(
                        source=device.name, category="app",
                        item_name=f"brew:{m.group(1)}",
                        current_version=m.group(2).strip(),
                    ))
        elif source_tag == "pip":
            for line in out.splitlines():
                if " " in line and not line.startswith("-") and not line.startswith("Package"):
                    parts = line.split()
                    if len(parts) >= 2:
                        records.append(VersionRecord(
                            source=device.name, category="library",
                            item_name=f"pip:{parts[0]}",
                            current_version=parts[1],
                        ))
        elif source_tag in ("win_apps",):
            try:
                apps = json.loads(out)
                if isinstance(apps, list):
                    for app in apps:
                        name = app.get("DisplayName", "")
                        ver = app.get("DisplayVersion", "")
                        if name:
                            records.append(VersionRecord(
                                source=device.name, category="app",
                                item_name=name, current_version=ver,
                            ))
            except:
                pass
        elif source_tag == "kernel":
            records.append(VersionRecord(
                source=device.name, category="system",
                item_name="kernel", current_version=out.strip()[:80],
            ))
        elif source_tag == "macos_version":
            records.append(VersionRecord(
                source=device.name, category="system",
                item_name="macOS", current_version=out.strip()[:80],
            ))

    client.close()
    print(f"    ✅ 收集到 {len(records)} 条记录")
    return records


# ══════════════════════════════════════════════════════════════════
#  模块三: Docker 镜像版本扫描
# ══════════════════════════════════════════════════════════════════

def scan_docker_images() -> List[VersionRecord]:
    """扫描本地 Docker 镜像并检查 registry 最新版本"""
    records: List[VersionRecord] = []

    # 检测 docker 是否可用
    rc, out = run_cmd(["docker", "info", "--format", "{{.ServerVersion}}"])
    if rc != 0:
        print("  ⚠  Docker 未运行或未安装")
        return records

    docker_ver = out.strip()
    print(f"  🐳 Docker 版本: {docker_ver}")
    records.append(VersionRecord(
        source="docker_host", category="system",
        item_name="docker_engine", current_version=docker_ver,
    ))

    # 列出所有本地镜像
    rc, out = run_cmd(["docker", "images", "--format", "{{json .}}"])
    if rc != 0 or not out.strip():
        return records

    images = []
    for line in out.strip().splitlines():
        try:
            img = json.loads(line)
            images.append(img)
        except:
            pass

    print(f"  🐳 发现 {len(images)} 个本地镜像, 正在检查更新...")

    for img in images:
        repo = img.get("Repository", "")
        tag = img.get("Tag", "latest")
        img_id = img.get("ID", "")[:12]
        created = img.get("CreatedAt", "")

        if not repo or repo == "<none>":
            continue

        rec = VersionRecord(
            source="docker_host",
            category="docker",
            item_name=f"{repo}:{tag}",
            current_version=tag,
            extra=f"ID:{img_id} Created:{created}",
        )

        # 尝试从 registry 获取最新版本
        # 处理官方镜像 (library/) 和私有仓库
        latest_tag = check_docker_latest(repo)
        if latest_tag:
            rec.latest_version = latest_tag
            rec.status = compare_versions(tag, latest_tag)
        else:
            rec.status = "unknown"

        records.append(rec)

    return records


def check_docker_latest(repo: str) -> Optional[str]:
    """查询 Docker Hub 或 registry 的最新 tag"""
    # 跳过私有仓库前缀
    if "/" in repo and "." in repo.split("/")[0]:
        return None  # 私有 registry, 跳过自动检查

    # 官方镜像: library/name 或 name
    api_repo = repo
    if "/" not in repo:
        api_repo = f"library/{repo}"

    # 先尝试 Docker Hub API v2 取 tag list
    url = f"https://hub.docker.com/v2/repositories/{api_repo}/tags/?page_size=25&ordering=last_updated"
    data = fetch_json(url)
    if data and "results" in data:
        tags = data["results"]
        # 过滤掉含非数字字符多的 tag, 优先选 semver 风格的
        version_tags = []
        for t in tags:
            name = t.get("name", "")
            # 跳过明显不是版本的 tag
            if re.search(r"(latest|alpine|slim|buster|bullseye|bookworm)", name, re.I):
                continue
            if re.match(r"^[\d.]+", name):
                version_tags.append(name)
        if version_tags:
            # 按 semver 排序取最大
            return max(version_tags, key=lambda x: semver_key(x))

    # fallback: Docker Hub API v1
    url = f"https://index.docker.io/v1/repositories/{api_repo}/tags"
    data = fetch_json(url)
    if data and isinstance(data, list):
        tags = [d.get("name", "") for d in data]
        version_tags = [t for t in tags if re.match(r"^[\d.]+", t)]
        if version_tags:
            return max(version_tags, key=lambda x: semver_key(x))

    return None


# ══════════════════════════════════════════════════════════════════
#  模块四: 手动录入 + 设备 App 追踪
# ══════════════════════════════════════════════════════════════════

def add_manual_app(device_name: str, app_name: str, version: str):
    """手动录入一个设备上的 App 版本"""
    cfg = load_config()
    if "manual_apps" not in cfg:
        cfg["manual_apps"] = {}

    if device_name not in cfg["manual_apps"]:
        cfg["manual_apps"][device_name] = {}

    # 检查是否已存在
    cfg["manual_apps"][device_name][app_name] = version
    save_config(cfg)
    print(f"  ✅ 已记录: {device_name} → {app_name} {version}")

    # 同时写入数据库
    db = get_db()
    rec = VersionRecord(
        source=device_name,
        category="app",
        item_name=app_name,
        current_version=version,
        status="unknown",
    )
    save_records(db, [rec])
    db.close()

def scan_manual_apps() -> List[VersionRecord]:
    """读取手动录入的 App 数据, 尝试在线查最新版本"""
    cfg = load_config()
    records: List[VersionRecord] = []
    manual = cfg.get("manual_apps", {})

    if not manual:
        return records

    for device_name, apps in manual.items():
        print(f"  📱 设备 {device_name}: 检查 {len(apps)} 个 App 更新...")
        for app_name, version in apps.items():
            rec = VersionRecord(
                source=device_name,
                category="app",
                item_name=app_name,
                current_version=version or "?",
            )
            # 尝试查询最新版本 (从 Google Play / App Store)
            latest = check_app_latest_version(app_name, device_name)
            if latest:
                rec.latest_version = latest
                rec.status = compare_versions(version or "", latest)
            records.append(rec)

    return records


def check_app_latest_version(app_name: str, device_hint: str = "") -> Optional[str]:
    """
    尝试从公开渠道获取 App 最新版本。
    目前通过 Google Play (Android) 和 App Store (iOS) 的公开接口。
    """
    # 先试试 App Store (iTunes API)
    # 搜索应用
    url = f"https://itunes.apple.com/search?term={urllib.parse.quote(app_name)}&limit=5&entity=software"
    data = fetch_json(url)
    if data and "results" in data.get("results", []):
        results = data["results"]
        if results:
            # 取最匹配的第一个
            ver = results[0].get("version", "")
            if ver:
                return ver

    # 再试试 Google Play (通过第三方 API 或网页爬)
    # 使用 Play 商店的公开页面
    try:
        url = f"https://play.google.com/store/apps/details?id={urllib.parse.quote(app_name)}"
        req = urllib.request.Request(url, headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
        })
        with urllib.request.urlopen(req, timeout=10) as resp:
            html_text = resp.read().decode("utf-8", errors="replace")
            # 找 "软件版本" 或 "Current Version"
            m = re.search(r'Current Version</div><div[^>]*>([^<]+)', html_text)
            if m:
                return m.group(1).strip()
    except:
        pass

    # 对于 Play Store 包名格式 com.example.app, 查 APKPure 等第三方
    if "." in app_name and app_name.count(".") >= 2:
        try:
            url = f"https://apkpure.com/{app_name.split('.')[-1]}/{app_name}"
            req = urllib.request.Request(url, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"
            })
            with urllib.request.urlopen(req, timeout=10) as resp:
                html_text = resp.read().decode("utf-8", errors="replace")
                m = re.search(r'<span class="ver">([^<]+)', html_text)
                if m:
                    return m.group(1).strip()
        except:
            pass

    return None


