        # 从数据库读取最近一次扫描结果
        latest_scan = db.execute(
            "SELECT MAX(scanned_at) FROM version_history"
        ).fetchone()[0]
        if latest_scan:
            rows = db.execute(
                "SELECT * FROM version_history WHERE scanned_at = ? ORDER BY category, source",
                (latest_scan,),
            ).fetchall()
        else:
            rows = db.execute(
                "SELECT * FROM version_history ORDER BY scanned_at DESC LIMIT 1000"
            ).fetchall()
    else:
        rows = [(None, r.source, r.category, r.item_name, r.current_version,
                 r.latest_version, r.status, r.scanned_at, r.extra) for r in records]

    db.close()

    # 统计
    total = len(rows)
