def show_history(days: int = 7):
    """显示最近 N 天的版本变更"""
    db = get_db()
    cutoff = (datetime.datetime.now() - datetime.timedelta(days=days)).isoformat()

    rows = db.execute(
        """SELECT scanned_at, source, category, item_name, current_version, latest_version, status
           FROM version_history WHERE scanned_at >= ?
           ORDER BY scanned_at DESC""",
        (cutoff,),
    ).fetchall()
    db.close()

    if not rows:
        print(f"  最近 {days} 天没有扫描记录")
        return

    # 按扫描批次分组
    batches: Dict[str, List] = {}
    for r in rows:
        scan_time = r[0]
        if scan_time not in batches:
            batches[scan_time] = []
        batches[scan_time].append(r)

    print(f"\n  📋 最近 {days} 天内的扫描历史 ({len(rows)} 条变更记录):\n")

    for scan_time in sorted(batches.keys(), reverse=True):
        items = batches[scan_time]
        outdated = sum(1 for r in items if r[6] == "outdated")
        dt = datetime.datetime.fromisoformat(scan_time)
        print(f"  ┌─ [{dt.strftime('%m-%d %H:%M')}] {len(items)} 条记录, {outdated} 个可更新")

        # 显示每个来源的前几条
        sources_shown = set()
        for r in items[:8]:
            if r[1] not in sources_shown:
                print(f"  │  📁 {r[1]}: {r[3]} ({r[4]}) → {r[5] or '?'} [{r[6]}]")
                sources_shown.add(r[1])
            elif len(sources_shown) < 3:
                print(f"  │  📁 {r[1]}: {r[3]} ({r[4]}) → {r[5] or '?'} [{r[6]}]")
        if len(items) > 8:
            print(f"  │  ... 还有 {len(items)-8} 条")
        print()


