def cmd_add_device(args):
    """添加 SSH 设备"""
    cfg = load_config()
    device = Device(
        name=args.name,
        type=args.type,
        host=args.host,
        port=args.port or 22,
        user=args.user or "",
        os_type=args.os or "",
        notes=args.notes or "",
    )
    # 检查重名
    for i, d in enumerate(cfg["devices"]):
        if d["name"] == args.name:
            cfg["devices"][i] = asdict(device)
            save_config(cfg)
            print(f"  ✅ 已更新设备: {args.name}")
            return
    cfg["devices"].append(asdict(device))
    save_config(cfg)
    print(f"  ✅ 已添加设备: {args.name}")


