def cmd_scan(args):
    """执行扫描"""
    cfg = load_config()
    db = get_db()
    all_records: List[VersionRecord] = []

    scan_deps = args.mode in ("deps", "all")
    scan_devices = args.mode in ("devices", "all")
    scan_docker_mode = args.mode in ("docker", "all")
    scan_manual = args.mode in ("manual", "all")

    # ── 扫描项目依赖 ──
    if scan_deps:
        projects = cfg.get("projects", [])
        if args.dir:
            # 直接扫描指定目录
            projects.append({"name": Path(args.dir).name, "path": args.dir, "pkg_managers": [], "notes": ""})

        if not projects:
            print("\n  ⚠  没有配置项目 (用 add project 添加, 或用 --dir 指定路径)")
        else:
            for proj_cfg in projects:
                proj = Project(**proj_cfg)
                print(f"\n  📁 扫描项目: {proj.name}")
                recs = scan_project_deps(proj)
                all_records += recs
                print(f"    → 共 {len(recs)} 条依赖记录")
                save_records(db, recs)

    # ── 扫描 SSH 设备 ──
    if scan_devices:
        devices = cfg.get("devices", [])
        if not devices:
            print("\n  ⚠  没有配置 SSH 设备 (用 add device 添加)")
        else:
            for dev_cfg in devices:
                dev = Device(**dev_cfg)
                print(f"\n  🔌 扫描设备: {dev.name}")
                recs = scan_ssh_device(dev)
                all_records += recs
                save_records(db, recs)

    # ── 扫描 Docker ──
    if scan_docker_mode:
        print("\n  🐳 扫描 Docker 镜像...")
        recs = scan_docker_images()
        all_records += recs
        save_records(db, recs)
        print(f"    → 共 {len(recs)} 条镜像记录")

    # ── 扫描手动录入 App ──
    if scan_manual:
        print("\n  📱 扫描手动录入的 App...")
        recs = scan_manual_apps()
        all_records += recs
        save_records(db, recs)
        print(f"    → 共 {len(recs)} 条 App 记录")

    db.close()

    # 汇总
    outdated = sum(1 for r in all_records if r.status == "outdated")
    latest_count = sum(1 for r in all_records if r.status == "latest")
    errors = sum(1 for r in all_records if r.status == "error")

    print(f"\n  {'='*45}")
    print(f"  📊 扫描完成: {len(all_records)} 条记录")
    print(f"     🔄 可更新: {outdated}")
    print(f"     ✅ 已最新: {latest_count}")
    print(f"     ⚠ 错误:   {errors}")
    print(f"     ❓ 未知:   {len(all_records) - outdated - latest_count - errors}")

    if args.report:
        print(f"\n  📄 正在生成报告...")
        report_path = generate_report(all_records)
        if args.open:
            import webbrowser
            webbrowser.open(f"file://{report_path}")
            print(f"  🌐 已在浏览器打开")


