def main():
    parser = argparse.ArgumentParser(
        description=f"Version Sentry v{VERSION} — 跨设备版本更新跟踪与决策工具",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=textwrap.dedent("""\
            示例:
              # 初始化
              python version-sentry.py init

              # 添加 SSH 设备
              python version-sentry.py add device --name old-mac --type ssh --host 192.168.1.100 --os macos

              # 添加项目
              python version-sentry.py add project --name myapp --path ./myapp

              # 扫描全部 + 生成报告
              python version-sentry.py scan all --report --open

              # 直接扫描一个目录的依赖
              python version-sentry.py scan deps --dir ./my-project --report
        """),
    )
    parser.add_argument("--version", action="version", version=f"%(prog)s {VERSION}")
    sub = parser.add_subparsers(dest="command", help="子命令")

    # init
    p_init = sub.add_parser("init", help="初始化配置")

    # add device
    p_dev = sub.add_parser("add-device", aliases=["add device"], help="添加 SSH 设备")
    p_dev.add_argument("--name", required=True)
    p_dev.add_argument("--type", default="ssh", choices=["ssh", "local", "manual"])
    p_dev.add_argument("--host", default="")
    p_dev.add_argument("--port", type=int, default=22)
    p_dev.add_argument("--user", default="")
    p_dev.add_argument("--os", default="", choices=["linux", "windows", "macos", ""])
    p_dev.add_argument("--notes", default="")

    # add project
    p_proj = sub.add_parser("add-project", aliases=["add project"], help="添加项目")
    p_proj.add_argument("--name", required=True)
    p_proj.add_argument("--path", required=True)
    p_proj.add_argument("--managers", default="", help="逗号分隔: npm,pip,cargo,go")
    p_proj.add_argument("--notes", default="")

    # add app (manual)
    p_app = sub.add_parser("add-app", aliases=["add app"], help="手动录入设备 App 版本")
    p_app.add_argument("--device", required=True, help="设备名称")
    p_app.add_argument("--name", required=True, help="App 名称")
    p_app.add_argument("--version", required=True, help="当前版本号")

    # scan
    p_scan = sub.add_parser("scan", help="执行扫描")
    p_scan.add_argument("mode", choices=["deps", "devices", "docker", "manual", "all"],
                        help="扫描模式")
    p_scan.add_argument("--dir", default="", help="直接扫描指定目录的依赖 (仅 deps 模式)")
    p_scan.add_argument("--report", action="store_true", help="自动生成 HTML 报告")
    p_scan.add_argument("--open", action="store_true", help="生成报告后浏览器打开")

    # report
    p_rep = sub.add_parser("report", help="生成 HTML 报告 (最近一次扫描)")
    p_rep.add_argument("--open", action="store_true", help="浏览器打开")

    # history
    p_hist = sub.add_parser("history", help="查看版本扫描历史")
    p_hist.add_argument("--days", type=int, default=7, help="最近 N 天 (默认 7)")

    # list
    sub.add_parser("list", help="列出所有配置")

    # 解析
    args = parser.parse_args()

    if not args.command:
        parser.print_help()
        return

    # 子命令映射 (处理别名)
    cmd_map = {
        "init": cmd_init,
        "add-device": cmd_add_device,
        "add device": cmd_add_device,
        "add-project": cmd_add_project,
        "add project": cmd_add_project,
        "add-app": cmd_add_app,
        "add app": cmd_add_app,
        "scan": cmd_scan,
        "report": cmd_report,
        "history": cmd_history,
        "list": cmd_list,
    }

    cmd = cmd_map.get(args.command)
    if cmd:
        cmd(args)
    else:
        parser.print_help()


if __name__ == "__main__":
    main()
"}

