{"path": "check-updates.py", "content": "#!/usr/bin/env python3
"""
check-updates.py — 本机版本更新检查三合一
===================================================
在一个脚本里完成:
  📦 1. 项目依赖 (npm/pip/cargo/go) → 查 registry 最新版
  🐳 2. Docker 镜像              → 查 Hub 最新 tag
  📱 3. 手动录入的 App          → 查 App Store / Play 最新版

用法:
  python check-updates.py                     # 扫描全部 + 显示摘要
  python check-updates.py --report            # 扫描 + 生成 HTML 报告
  python check-updates.py --open              # 扫描 + 浏览器打开报告
  python check-updates.py --dir ./my-project  # 只看指定目录的依赖
  python check-updates.py --add-app "WeChat"  # 手动添加一个 App
  python check-updates.py history             # 查看历史记录
  python check-updates.py list-apps           # 列出已录入的 App

首次运行自动创建配置文件。
===================================================
"""

from __future__ import annotations

import argparse
import datetime
import html
import json
import os
import re
import sqlite3
import subprocess
import sys
import textwrap
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass, field, asdict
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

VERSION = "1.0.0"
CONFIG_DIR = Path.home() / ".check-updates"
CONFIG_FILE = CONFIG_DIR / "config.json"
DB_FILE = CONFIG_DIR / "history.db"
REPORT_DIR = CONFIG_DIR / "reports"

DEFAULT_CONFIG = {
    "projects": [],          # [{name, path, managers}]
    "manual_apps": {},       # {"app_name": "current_version"}
    "docker_enabled": True,
}


# ── 数据模型 ──────────────────────────────────────────────────────


@dataclass
class VersionRecord:
    source: str       # 项目名 / "manual" / "docker"
    category: str     # "npm" / "pip" / "cargo" / "go" / "app" / "docker"
    item_name: str    # 包名 / 应用名 / 镜像名
    current: str
    latest: str = ""
    status: str = "unknown"   # latest / outdated / unknown / error
    extra: str = ""


# ── 配置 ──────────────────────────────────────────────────────────


def load_config() -> dict:
    if not CONFIG_FILE.exists():
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        CONFIG_FILE.write_text(
            json.dumps(DEFAULT_CONFIG, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        return dict(DEFAULT_CONFIG)
    return json.loads(CONFIG_FILE.read_text(encoding="utf-8"))


def save_config(cfg: dict):
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    CONFIG_FILE.write_text(
        json.dumps(cfg, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )


# ── 数据库 ────────────────────────────────────────────────────────


def get_db() -> sqlite3.Connection:
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(str(DB_FILE))
    db.execute("""
        CREATE TABLE IF NOT EXISTS history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            scanned_at TEXT NOT NULL,
            source TEXT NOT NULL,
            category TEXT NOT NULL,
            item_name TEXT NOT NULL,
            current_ver TEXT NOT NULL,
            latest_ver TEXT DEFAULT '',
            status TEXT DEFAULT 'unknown',
            extra TEXT DEFAULT ''
        )
    """)
    db.execute("""
        CREATE INDEX IF NOT EXISTS idx_scan_time ON history(scanned_at)
    """)
    db.commit()
    return db


def save_records(db: sqlite3.Connection, records: List[VersionRecord]):
    now = datetime.datetime.now().isoformat(timespec="seconds")
    for r in records:
        db.execute(
            "INSERT INTO history (scanned_at, source, category, item_name, current_ver, latest_ver, status, extra) VALUES (?,?,?,?,?,?,?,?)",
            (now, r.source, r.category, r.item_name, r.current, r.latest, r.status, r.extra),
        )
    db.commit()


# ── 工具 ──────────────────────────────────────────────────────────


def fetch_json(url: str, timeout: int = 15) -> Optional[dict]:
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "check-updates/1.0"})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except Exception:
        return None


def fetch_text(url: str, timeout: int = 15) -> Optional[str]:
    try:
        req = urllib.request.Request(url, headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
        })
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.read().decode("utf-8", errors="replace")
    except Exception:
        return None


def semver_key(v: str) -> tuple:
    parts = re.findall(r"\d+", v)
    return tuple(int(p) for p in parts) if parts else (0,)


def cmp_ver(current: str, latest: str) -> str:
    if not latest or not current:
        return "unknown"
    if current.strip() == latest.strip():
        return "latest"
    try:
        return "outdated" if semver_key(latest) > semver_key(current) else "latest"
    except Exception:
        return "unknown"


def banner(text: str):
    width = 60
    print(f"\n  {'─' * width}")
    print(f"  {text}")
    print(f"  {'─' * width}")


# ══════════════════════════════════════════════════════════════════
#  模块 1: 项目依赖扫描
# ══════════════════════════════════════════════════════════════════


def scan_project(path: Path, name: str = "", managers: List[str] | None = None) -> List[VersionRecord]:
    """扫描一个项目目录的过时依赖"""
    if not managers:
        managers = _detect(path)

    records: List[VersionRecord] = []
    if "npm" in managers:
        records += _scan_npm(path, name)
    if "pip" in managers:
        records += _scan_pip(path, name)
    if "cargo" in managers:
        records += _scan_cargo(path, name)
    if "go" in managers:
        records += _scan_go(path, name)
    return records


def _detect(path: Path) -> List[str]:
    mgrs = []
    if (path / "package.json").exists():
        mgrs.append("npm")
    if (path / "requirements.txt").exists() or (path / "pyproject.toml").exists():
        mgrs.append("pip")
    if (path / "Cargo.toml").exists():
        mgrs.append("cargo")
    if (path / "go.mod").exists():
        mgrs.append("go")
    return mgrs


# ─ npm ─

def _scan_npm(path: Path, source: str) -> List[VersionRecord]:
    pkg_json = path / "package.json"
    if not pkg_json.exists():
        return []
    try:
        data = json.loads(pkg_json.read_text(encoding="utf-8"))
    except Exception:
        return []

    deps = {**data.get("dependencies", {}), **data.get("devDependencies", {})}
    if not deps:
        return []

    records: List[VersionRecord] = []
    total = len(deps)
    for i, (pkg, ver) in enumerate(deps.items(), 1):
        current = ver.lstrip("^~>=<! ")
        rec = VersionRecord(source=source or path.name, category="npm", item_name=pkg, current=current)
        data = fetch_json(f"https://registry.npmjs.org/{urllib.parse.quote(pkg, safe='')}/latest")
        if data and "version" in data:
            rec.latest = data["version"]
            rec.status = cmp_ver(current, data["version"])
        records.append(rec)
        _progress(i, total, f"npm: {pkg}")

    return records


# ─ pip ─

def _scan_pip(path: Path, source: str) -> List[VersionRecord]:
    pkgs: Dict[str, str] = {}

    # requirements.txt
    req = path / "requirements.txt"
    if req.exists():
        for line in req.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line or line.startswith("#") or line.startswith("-"):
                continue
            m = re.match(r"([a-zA-Z0-9_.-]+)\s*([><=~!]+\s*[\d.*]+)?", line)
            if m:
                pkgs[m.group(1).lower()] = (m.group(2) or "").lstrip("=~>< ")

    # pyproject.toml (极简)
    pyproj = path / "pyproject.toml"
    if pyproj.exists():
        in_project = False
        for line in pyproj.read_text(encoding="utf-8").splitlines():
            s = line.strip()
            if s.startswith("[project"):
                in_project = True; continue
            if in_project and s.startswith("["):
                in_project = False
            if in_project and ('"' in s or "'" in s):
                m = re.match(r"""['"]([a-zA-Z0-9_.-]+)([><=~!][\d.*]+)?['"]""", s.strip(","))
                if m and m.group(1):
                    pkgs[m.group(1).lower()] = (m.group(2) or "").lstrip("=~><")

    if not pkgs:
        return []

    records: List[VersionRecord] = []
    total = len(pkgs)
    for i, (pkg, ver) in enumerate(pkgs.items(), 1):
        rec = VersionRecord(source=source or path.name, category="pip", item_name=pkg, current=ver or "?")
        data = fetch_json(f"https://pypi.org/pypi/{urllib.parse.quote(pkg, safe='')}/json")
        if data and "info" in data and "version" in data["info"]:
            rec.latest = data["info"]["version"]
            rec.status = cmp_ver(ver, data["info"]["version"])
        records.append(rec)
        _progress(i, total, f"pip: {pkg}")

    return records


# ─ cargo ─

def _scan_cargo(path: Path, source: str) -> List[VersionRecord]:
    cargo = path / "Cargo.toml"
    if not cargo.exists():
        return []

    text = cargo.read_text(encoding="utf-8")
    deps: Dict[str, str] = {}
    in_deps = False
    for line in text.splitlines():
        s = line.strip()
        if s.startswith("[dependencies"):
            in_deps = True; continue
        if in_deps and s.startswith("["):
            in_deps = False
        if in_deps and "=" in s and not s.startswith("#"):
            parts = s.split("=", 1)
            name = parts[0].strip()
            ver = parts[1].strip().strip('"').strip("'")
            if name and ver and not ver.startswith("{") and not ver.startswith("git"):
                deps[name] = ver

    records: List[VersionRecord] = []
    total = len(deps)
    for i, (pkg, ver) in enumerate(deps.items(), 1):
        rec = VersionRecord(source=source or path.name, category="cargo", item_name=pkg, current=ver)
        data = fetch_json(f"https://crates.io/api/v1/crates/{urllib.parse.quote(pkg, safe='')}")
        if data and "crate" in data and "max_version" in data["crate"]:
            rec.latest = data["crate"]["max_version"]
            rec.status = cmp_ver(ver, data["crate"]["max_version"])
        records.append(rec)
        _progress(i, total, f"cargo: {pkg}")

    return records


# ─ go ─

def _scan_go(path: Path, source: str) -> List[VersionRecord]:
    gomod = path / "go.mod"
    if not gomod.exists():
        return []

    deps: Dict[str, str] = {}
    for line in gomod.read_text(encoding="utf-8").splitlines():
        m = re.match(r"([a-zA-Z0-9_./-]+)\s+v?([\d.]+)", line.strip())
        if m and "require" not in line.strip() and line.strip() != ")":
            deps[m.group(1)] = m.group(2)

    records: List[VersionRecord] = []
    total = len(deps)
    for i, (pkg, ver) in enumerate(deps.items(), 1):
        rec = VersionRecord(source=source or path.name, category="go", item_name=pkg, current=ver)
        try:
            req = urllib.request.Request(
                f"https://proxy.golang.org/{urllib.parse.quote(pkg, safe='')}/@latest",
                headers={"User-Agent": "check-updates/1.0"},
            )
            with urllib.request.urlopen(req, timeout=10) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                if "Version" in data:
                    rec.latest = data["Version"].lstrip("v")
                    rec.status = cmp_ver(ver, rec.latest)
        except Exception:
            pass
        records.append(rec)
        _progress(i, total, f"go: {pkg}")

    return records


def _progress(i: int, total: int, label: str):
    if total <= 1:
        return
    bar_len = 20
    filled = int(bar_len * i / total)
    bar = "█" * filled + "░" * (bar_len - filled)
    print(f"\r    [{bar}] {i}/{total}  {label:<40}", end="")
    if i == total:
        print()


# ══════════════════════════════════════════════════════════════════
#  模块 2: Docker 镜像版本扫描
# ══════════════════════════════════════════════════════════════════


def scan_docker() -> List[VersionRecord]:
    """扫描本地 Docker 镜像, 检查 registry 最新版本"""
    rc, out = run_cmd(["docker", "info", "--format", "{{.ServerVersion}}"])
    if rc != 0:
        print("  ⚠  Docker 未运行")
        return []

    records: List[VersionRecord] = []

    rc, out = run_cmd(["docker", "images", "--format", "{{json .}}"])
    if rc != 0 or not out.strip():
        return records

    images = []
    for line in out.strip().splitlines():
        try:
            images.append(json.loads(line))
        except json.JSONDecodeError:
            pass

    print(f"\n  🐳 发现 {len(images)} 个本地镜像, 正在查询更新...")
    for img in images:
        repo = img.get("Repository", "")
        tag = img.get("Tag", "latest")
        if not repo or repo == "<none>":
            continue

        rec = VersionRecord(
            source="docker",
            category="docker",
            item_name=f"{repo}:{tag}",
            current=tag,
            extra=f"ID:{img.get('ID','')[:12]}",
        )

        latest = _docker_latest_tag(repo)
        if latest:
            rec.latest = latest
            rec.status = cmp_ver(tag, latest)
        records.append(rec)
        print(f"    {repo}:{tag}  →  latest: {latest or '?'}  [{rec.status}]")

    return records


def _docker_latest_tag(repo: str) -> Optional[str]:
    """查 Docker Hub 最新 version tag"""
    api_repo = repo if "/" in repo else f"library/{repo}"

    # 跳过私有 registry
    if "/" in repo and "." in repo.split("/")[0]:
        return None

    data = fetch_json(f"https://hub.docker.com/v2/repositories/{api_repo}/tags/?page_size=50&ordering=last_updated")
    if data and "results" in data:
        vers = []
        for t in data["results"]:
            name = t.get("name", "")
            if re.match(r"^[\d.]+$", name):
                vers.append(name)
        if vers:
            return max(vers, key=semver_key)

    # fallback v1
    data = fetch_json(f"https://index.docker.io/v1/repositories/{api_repo}/tags")
    if data and isinstance(data, list):
        vers = [d["name"] for d in data if re.match(r"^[\d.]+$", d.get("name", ""))]
        if vers:
            return max(vers, key=semver_key)

    return None


def run_cmd(cmd: List[str], timeout: int = 15) -> Tuple[int, str]:
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return r.returncode, (r.stdout or "") + (r.stderr or "")
    except FileNotFoundError:
        return -1, ""
    except subprocess.TimeoutExpired:
        return -1, ""


# ══════════════════════════════════════════════════════════════════
#  模块 3: 手动录入 App 版本查询
# ══════════════════════════════════════════════════════════════════


def add_manual_app(name: str, version: str):
    """录入一个 App 的当前版本"""
    cfg = load_config()
    cfg.setdefault("manual_apps", {})
    cfg["manual_apps"][name] = version
    save_config(cfg)
    print(f"  ✅ 已录入: {name} = {version}")


def list_manual_apps():
    """列出已录入的 App"""
    cfg = load_config()
    apps = cfg.get("manual_apps", {})
    if not apps:
        print("  (空)")
        return
    print(f"  共 {len(apps)} 个 App:\n")
    for name, ver in apps.items():
        print(f"    📱 {name:<30} {ver}")


def scan_manual_apps() -> List[VersionRecord]:
    """检查手动录入 App 的最新版本"""
    cfg = load_config()
    apps = cfg.get("manual_apps", {})
    if not apps:
        return []

    records: List[VersionRecord] = []
    print(f"\n  📱 检查 {len(apps)} 个 App 的更新...")
    for name, ver in apps.items():
        rec = VersionRecord(source="manual", category="app", item_name=name, current=ver or "?")
        latest = _check_app_latest(name)
        if latest:
            rec.latest = latest
            rec.status = cmp_ver(ver, latest)
        records.append(rec)
        status_icon = {"latest": "✅", "outdated": "🔄", "unknown": "❓", "error": "⚠"}.get(rec.status, "❓")
        print(f"    {status_icon} {name:<30} {ver}  →  {latest or '?'}")

    return records


def _check_app_latest(name: str) -> Optional[str]:
    """从 App Store / Play Store 查 App 最新版本"""
    # App Store
    data = fetch_json(
        f"https://itunes.apple.com/search?term={urllib.parse.quote(name)}&limit=3&entity=software"
    )
    if data and data.get("results"):
        ver = data["results"][0].get("version")
        if ver:
            return ver

    # Google Play (通过 apkpure)
    # 先搜包名
    html_text = fetch_text(f"https://play.google.com/store/search?q={urllib.parse.quote(name)}&c=apps")
    if html_text:
        m = re.search(r'id=([a-zA-Z0-9.]+)', html_text)
        if m:
            pkg = m.group(1)
            html2 = fetch_text(f"https://apkpure.com/{name.lower().replace(' ','-')}/{pkg}")
            if html2:
                m2 = re.search(r'class="ver"[^>]*>([^<]+)', html2)
                if m2:
                    return m2.group(1).strip()
            # 另一个源
            html3 = fetch_text(f"https://www.apkmirror.com/?s={urllib.parse.quote(name)}")
            if html3:
                m3 = re.search(r'<div class="app-title">([^<]+)', html3)
                if m3:
                    pass  # APKMirror 版本号不好提取

    return None


# ══════════════════════════════════════════════════════════════════
#  报告生成
# ══════════════════════════════════════════════════════════════════


def generate_report(records: List[VersionRecord] | None = None) -> str:
    """生成 HTML 报告, 返回路径"""
    db = get_db()

    if records is None:
        latest_scan = db.execute("SELECT MAX(scanned_at) FROM history").fetchone()[0]
        if latest_scan:
            rows = db.execute(
                "SELECT * FROM history WHERE scanned_at = ? ORDER BY category, item_name",
                (latest_scan,),
            ).fetchall()
        else:
            rows = []
    else:
        rows = [(None, "", r.source, r.category, r.item_name, r.current, r.latest, r.status, r.extra) for r in records]

    db.close()

    total = len(rows)
    outdated = sum(1 for r in rows if r[7] == "outdated")
    latest = sum(1 for r in rows if r[7] == "latest")
    unknown = sum(1 for r in rows if r[7] == "unknown")

    # 按来源分组
    sources: Dict[str, List] = {}
