</style>
</head>
<body>
<h1>🔍 版本更新检查报告</h1>
<p class="sub">本机扫描 · {timestamp} · 共 {total} 条</p>
<div class="stats">
  <div class="stat"><div class="n">{total}</div><div class="l">总计</div></div>
  <div class="stat out"><div class="n">{outdated}</div><div class="l">🔄 可更新</div></div>
  <div class="stat ok"><div class="n">{latest}</div><div class="l">✅ 已最新</div></div>
  <div class="stat unk"><div class="n">{unknown}</div><div class="l">❓ 未知</div></div>
</div>
"""

    for src_name in sorted(sources.keys()):
        items = sources[src_name]
        o = src_outdated(src_name)
        label = f"{html.escape(src_name)}" + (f"  <span style='color:#e74c3c;font-size:0.85em'>({o} 可更新)</span>" if o else "")

        HTML += f"""<div class="sec">
<div class="sh"><span>{label}</span><span class="c">{len(items)} 项</span></div>
<table><thead><tr><th>名称</th><th>当前</th><th>最新</th><th>状态</th></tr></thead><tbody>
"""
        for r in items:
            _, _, _, cat, name, cur, lat, st, ext = r
            badge = f"b-{'out' if st=='outdated' else 'ok' if st=='latest' else 'unk'}"
            label_st = {"outdated": "🔄 可更新", "latest": "✅ 已最新", "unknown": "❓ 未知", "error": "⚠ 错误"}.get(st, st)
            ver_class = "new" if st == "outdated" else ""

            HTML += f"""<tr>
  <td><b>{html.escape(name)}</b><br><span style="font-size:0.75em;color:#999">{html.escape(cat)}</span></td>
