  <td class="mono {ver_class}">{html.escape(lat) if lat else "—"}</td>
  <td><span class="b {badge}">{label_st}</span></td>
</tr>
"""
        HTML += "</tbody></table></div>\n"

    HTML += f"""<div class="footer">check-updates.py v{VERSION}</div>
</body></html>"""

    REPORT_DIR.mkdir(parents=True, exist_ok=True)
    ts = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
    report_file = REPORT_DIR / f"report-{ts}.html"
    report_file.write_text(HTML, encoding="utf-8")

    # latest 软链
    latest_link = REPORT_DIR / "latest.html"
    try:
        if latest_link.exists():
            latest_link.unlink()
