    return str(report_file)


# ══════════════════════════════════════════════════════════════════
#  主流程
# ══════════════════════════════════════════════════════════════════


def run(args):
    cfg = load_config()
    db = get_db()
    all_records: List[VersionRecord] = []

    # 1. 项目依赖
    proj_targets: List[Tuple[Path, str, List[str]]] = []

    if args.dir:
        p = Path(args.dir).expanduser().resolve()
        if p.is_dir():
            proj_targets.append((p, p.name, _detect(p)))
        else:
            print(f"  ⚠  目录不存在: {p}")
    else:
        for pcfg in cfg.get("projects", []):
            p = Path(pcfg["path"]).expanduser().resolve()
            if p.is_dir():
                proj_targets.append((p, pcfg.get("name", p.name), pcfg.get("pkg_managers", [])))
            else:
                print(f"  ⚠  项目路径不存在: {pcfg['path']}")

    if proj_targets:
        banner("📦 扫描项目依赖")
        for p, name, mgrs in proj_targets:
            print(f"\n  项目: {name}  ({p})")
            recs = scan_project(p, name, mgrs)
            all_records += recs
            outdated = sum(1 for r in recs if r.status == "outdated")
            print(f"\n    → {len(recs)} 个依赖, {outdated} 个可更新")
            save_records(db, recs)

    # 2. Docker
    if cfg.get("docker_enabled", True):
        banner("🐳 扫描 Docker 镜像")
        recs = scan_docker()
        all_records += recs
        outdated = sum(1 for r in recs if r.status == "outdated")
        print(f"  → {len(recs)} 个镜像, {outdated} 个可更新")
        save_records(db, recs)
    else:
        print("\n  🐳 Docker 扫描已禁用")

    # 3. 手动 App
    banner("📱 手动录入 App")
    recs = scan_manual_apps()
    all_records += recs
    outdated = sum(1 for r in recs if r.status == "outdated")
    print(f"  → {len(recs)} 个 App, {outdated} 个可更新")
    save_records(db, recs)

    db.close()

    # 汇总
    total = len(all_records)
    outdated = sum(1 for r in all_records if r.status == "outdated")
    latest_c = sum(1 for r in all_records if r.status == "latest")
    unknown = sum(1 for r in all_records if r.status == "unknown")

    banner("📊 扫描结果汇总")
    print(f"    总计:    {total}")
    print(f"    🔄 可更新: {outdated}")
    print(f"    ✅ 已最新: {latest_c}")
    print(f"    ❓ 未知:   {unknown}")
    print(f"    {'─' * 40}")
    print(f"    💡 运行 python check-updates.py --report --open 生成 HTML 报告")

    if args.report:
        print()
        rp = generate_report(all_records)
        if args.open:
            try:
                import webbrowser
                webbrowser.open(f"file://{rp}")
                print("  🌐 已打开浏览器")
            except Exception:
                pass


# ══════════════════════════════════════════════════════════════════
#  入口
# ══════════════════════════════════════════════════════════════════


def main():
    parser = argparse.ArgumentParser(
        description=f"check-updates v{VERSION} — 本机版本更新检查三合一",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=textwrap.dedent("""\
            示例:
              python check-updates.py                     # 全扫描 + 终端摘要
              python check-updates.py --report --open     # 扫描 + 浏览器看报告
              python check-updates.py --dir ./my-app      # 只看某个目录
              python check-updates.py --add-app "WeChat"  # 添加一个 App
              python check-updates.py --add-app "WeChat" --version 8.0.44
              python check-updates.py list-apps           # 列出已录入 App
              python check-updates.py history             # 最近历史
        """),
    )
    parser.add_argument("--dir", help="只扫描指定目录的依赖", default="")
    parser.add_argument("--report", action="store_true", help="生成 HTML 报告")
    parser.add_argument("--open", action="store_true", help="报告生成后浏览器打开")
    parser.add_argument("--add-app", metavar="NAME", help="手动录入一个 App")
    parser.add_argument("--version", help="--add-app 时的版本号")
    parser.add_argument("list-apps", nargs="?", const=True, help="列出已录入 App")
    parser.add_argument("history", nargs="?", const=True, help="查看近期历史")
    parser.add_argument("--days", type=int, default=7, help="history 天数")

    args = parser.parse_args()

    # 特殊子命令
    if args.list_apps:
        list_manual_apps()
        return

    if args.history:
        show_history(args.days)
        return

    if args.add_app:
        add_manual_app(args.add_app, args.version or input(f"  {args.add_app} 当前版本: ").strip())
        return

    run(args)


def show_history(days: int = 7):
    db = get_db()
    cutoff = (datetime.datetime.now() - datetime.timedelta(days=days)).isoformat()
    rows = db.execute(
        """SELECT scanned_at, source, category, item_name, current_ver, latest_ver, status
           FROM history WHERE scanned_at >= ? ORDER BY scanned_at DESC LIMIT 100""",
        (cutoff,),
    ).fetchall()
    db.close()

    if not rows:
        print(f"  最近 {days} 天无记录")
        return

    by_time: Dict[str, List] = {}
    for r in rows:
        by_time.setdefault(r[0], []).append(r)

    print(f"\n  📋 最近 {days} 天 ({len(rows)} 条记录):\n")
    for scan_time in sorted(by_time.keys(), reverse=True)[:5]:
        items = by_time[scan_time]
        o = sum(1 for r in items if r[6] == "outdated")
        dt = datetime.datetime.fromisoformat(scan_time)
        print(f"  [{dt.strftime('%m-%d %H:%M')}] {len(items)} 条  |  {o} 个可更新")
        for r in items[:6]:
            icon = {"outdated": "🔄", "latest": "✅", "unknown": "❓"}.get(r[6], "❓")
            print(f"    {icon} {r[2]}:{r[3]}  {r[4]} → {r[5] or '?'}")
        if len(items) > 6:
            print(f"    ... 还有 {len(items)-6} 条")
        print()


if __name__ == "__main__":
    main()
"}

{"content": "#!/usr/bin/env python3
"""
check-updates — 本机版本更新检查
===================================
组合借鉴: Dependabot / Renovate / Watchtower / Diun 的设计思路

本机一站式检查:
  📦 依赖更新 — 用各语言原生命令 (npm outdated, pip list --outdated, cargo outdated ...)
  🐳 镜像更新 — 类似 Watchtower, 查 Docker registry 最新 tag
  📱 App 更新  — 手动录入 + 自动查 App Store / Play Store

用法:
  python check-updates.py                  # 执行全部检查
  python check-updates.py --report --open  # 生成 HTML 报告并打开
  python check-updates.py deps --dir .     # 只看某个目录的依赖
  python check-updates.py docker           # 只看 Docker
  python check-updates.py app add ...      # 录入 App
  python check-updates.py app list         # 列出 App
  python check-updates.py history          # 历史记录
"""

from __future__ import annotations

import argparse
import datetime
import html
import json
import os
import re
import sqlite3
import subprocess
import sys
import textwrap
import urllib.request
import urllib.parse
import urllib.error
from dataclasses import dataclass, field, asdict
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

VERSION = "2.0.0"
CONFIG_DIR = Path.home() / ".check-updates"
CONFIG_FILE = CONFIG_DIR / "config.json"
DB_FILE = CONFIG_DIR / "history.db"
REPORT_DIR = CONFIG_DIR / "reports"

DEFAULT_CONFIG = {
    "projects": [],
    "manual_apps": {},
    "docker_enabled": True,
}


# ── 数据模型 ──────────────────────────────────────────────────────


@dataclass
class Record:
    source: str
    category: str  # npm / pip / cargo / go / docker / app
    item: str
    current: str
    latest: str = ""
    status: str = "unknown"  # latest / outdated / unknown / error
    extra: str = ""


# ── 配置 ──────────────────────────────────────────────────────────


def load_config() -> dict:
    if not CONFIG_FILE.exists():
        CONFIG_DIR.mkdir(parents=True, exist_ok=True)
        CONFIG_FILE.write_text(json.dumps(DEFAULT_CONFIG, ensure_ascii=False, indent=2), encoding="utf-8")
        return dict(DEFAULT_CONFIG)
    return json.loads(CONFIG_FILE.read_text(encoding="utf-8"))


def save_config(cfg: dict):
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    CONFIG_FILE.write_text(json.dumps(cfg, ensure_ascii=False, indent=2), encoding="utf-8")


# ── 数据库 ────────────────────────────────────────────────────────


def get_db() -> sqlite3.Connection:
    CONFIG_DIR.mkdir(parents=True, exist_ok=True)
    db = sqlite3.connect(str(DB_FILE))
    db.execute("""CREATE TABLE IF NOT EXISTS history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        scanned_at TEXT, source TEXT, category TEXT,
        item_name TEXT, current_ver TEXT, latest_ver TEXT,
        status TEXT, extra TEXT
    )""")
    db.execute("CREATE INDEX IF NOT EXISTS idx_scan ON history(scanned_at)")
    db.commit()
    return db


def save_records(db: sqlite3.Connection, records: List[Record]):
    now = datetime.datetime.now().isoformat(timespec="seconds")
    for r in records:
        db.execute(
            "INSERT INTO history (scanned_at,source,category,item_name,current_ver,latest_ver,status,extra) VALUES (?,?,?,?,?,?,?,?)",
            (now, r.source, r.category, r.item, r.current, r.latest, r.status, r.extra),
        )
    db.commit()


# ── 工具 ──────────────────────────────────────────────────────────


def run(cmd: List[str], timeout: int = 30) -> Tuple[int, str]:
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return r.returncode, r.stdout or ""
    except FileNotFoundError:
        return -1, ""
    except subprocess.TimeoutExpired:
        return -1, ""


def fetch(url: str, timeout: int = 15) -> Optional[dict]:
    try:
        req = urllib.request.Request(url, headers={"User-Agent": f"check-updates/{VERSION}"})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except Exception:
        return None


def semver_sort_key(v: str) -> tuple:
    parts = re.findall(r"\d+", v)
    return tuple(int(p) for p in parts) if parts else (0,)


def cmp_ver(cur: str, lat: str) -> str:
    if not lat or not cur:
        return "unknown"
    if cur.strip() == lat.strip():
        return "latest"
    try:
        return "outdated" if semver_sort_key(lat) > semver_sort_key(cur) else "latest"
    except Exception:
        return "unknown"


# ══════════════════════════════════════════════════════════════════
#  模块 1: 依赖更新 — 借鉴 Renovate / Dependabot 思路
#  核心原则: 用各语言原生命令, 不自己实现版本比较
# ══════════════════════════════════════════════════════════════════


def scan_deps(path: Path) -> List[Record]:
    """检测项目类型, 委托给各语言的 outdated 命令"""
    records: List[Record] = []

    # ── npm ── 借鉴 Renovate: 用 npm outdated --json
    if (path / "package.json").exists():
        records += _npm_outdated(path)

    # ── pip ── 借鉴 Dependabot: 用 pip list --outdated --format=json
    if (path / "requirements.txt").exists() or (path / "pyproject.toml").exists():
        records += _pip_outdated(path)

    # ── cargo ── 借鉴 Renovate: 用 cargo outdated
    if (path / "Cargo.toml").exists():
        records += _cargo_outdated(path)

    # ── go ── 借鉴 Dependabot: 用 go list -u -m
    if (path / "go.mod").exists():
        records += _go_outdated(path)

    return records


def _npm_outdated(path: Path) -> List[Record]:
    """npm outdated --json → 解析输出
    借鉴 Renovate: 它用 npm outdated 的输出做 diff, 而不是自己算版本"""
    rc, out = run(["npm", "outdated", "--json", "--prefix", str(path)])
    if rc != 0 and not out.strip():
        # npm outdated 非零退出也可能有输出 (有 outdated 包时)
        return []

    try:
        data = json.loads(out)
    except json.JSONDecodeError:
        return []

    records: List[Record] = []
    for pkg, info in data.items():
        records.append(Record(
            source=path.name,
            category="npm",
            item=pkg,
            current=info.get("current", "?"),
            latest=info.get("latest", info.get("wanted", "?")),
            status="outdated",
        ))
    return records


def _pip_outdated(path: Path) -> List[Record]:
    """pip list --outdated --format=json
    借鉴 Dependabot: 用 pip 自己的输出来判断, 不自己解析 requirements.txt"""
    rc, out = run([sys.executable, "-m", "pip", "list", "--outdated", "--format=json"],
                  timeout=60)
    if rc != 0 or not out.strip():
        return []

    try:
        data = json.loads(out)
    except json.JSONDecodeError:
        return []

    records: List[Record] = []
    for pkg in data:
        records.append(Record(
            source=path.name,
            category="pip",
            item=pkg.get("name", "?"),
            current=pkg.get("version", "?"),
            latest=pkg.get("latest_version", "?"),
            status="outdated",
        ))
    return records


def _cargo_outdated(path: Path) -> List[Record]:
    """cargo outdated --format=json
    借鉴 Renovate 的 Cargo 模块: 用 cargo outdated 的输出"""
    rc, out = run(["cargo", "outdated", "--format=json"], timeout=120, cwd=str(path))
    # 如果 cargo-outdated 没装, 提示
    if rc != 0:
        if "no such command" in out.lower() or "not found" in out.lower():
            print("  ⚠  cargo-outdated 未安装. 运行: cargo install cargo-outdated")
        return []

    try:
        data = json.loads(out)
    except json.JSONDecodeError:
        return []

    records: List[Record] = []
    deps = data.get("dependencies", []) if isinstance(data, dict) else data
    for dep in deps:
        name = dep.get("name", dep.get("package", "?"))
        records.append(Record(
            source=path.name,
            category="cargo",
            item=name,
            current=dep.get("project_version", dep.get("current", "?")),
            latest=dep.get("latest_version", dep.get("latest", "?")),
            status="outdated",
        ))
    return records


def _go_outdated(path: Path) -> List[Record]:
    """go list -u -m all
    借鉴 Dependabot: 用 go 自身的工具链输出"""
    rc, out = run(["go", "list", "-u", "-m", "all"], timeout=120, cwd=str(path))
    if rc != 0 or not out.strip():
        return []

    records: List[Record] = []
    for line in out.splitlines():
        parts = line.split()
        # 格式: pkg current_version [latest_version]
        if len(parts) >= 3 and "[" in parts[-1]:
            name = parts[0]
            cur = parts[1]
            lat = parts[-1].strip("[]")
            records.append(Record(
                source=path.name,
                category="go",
                item=name,
                current=cur,
                latest=lat,
                status="outdated",
            ))
    return records


# ══════════════════════════════════════════════════════════════════
#  模块 2: Docker 镜像 — 借鉴 Watchtower / Diun
#  思路: 读取本地镜像 → registry API 查最新 digest/tag
# ══════════════════════════════════════════════════════════════════


def scan_docker() -> List[Record]:
    """类似 Watchtower: 遍历本地容器/镜像, 查 registry 更新"""
    rc, out = run(["docker", "info", "--format", "{{.ServerVersion}}"])
    if rc != 0:
        print("  ⚠  Docker 未运行")
        return []

    docker_ver = out.strip()
    print(f"  🐳 Docker Engine: {docker_ver}")

    # 先查正在运行的容器 (Watchtower 做法)
    rc_ps, out_ps = run(["docker", "ps", "--format", "{{json .}}"])
    containers = []
    if rc_ps == 0 and out_ps.strip():
        for line in out_ps.strip().splitlines():
            try:
                containers.append(json.loads(line))
            except json.JSONDecodeError:
                pass

    if containers:
        print(f"     运行中容器: {len(containers)}")

    # 查所有镜像 (Diun 做法: 扫描全部镜像)
    rc_img, out_img = run(["docker", "images", "--format", "{{json .}}"])
    if rc_img != 0 or not out_img.strip():
        return []

    images = []
    for line in out_img.strip().splitlines():
        try:
            images.append(json.loads(line))
        except json.JSONDecodeError:
            pass

    records: List[Record] = []
    seen: set = set()

    for img in images:
        repo = img.get("Repository", "")
        tag = img.get("Tag", "latest")
        if not repo or repo == "<none>" or (repo, tag) in seen:
            continue
        seen.add((repo, tag))

        # 跳过私有 registry (含点号 + 端口)
        if "/" in repo and (repo.split("/")[0].count(".") > 0 or ":" in repo.split("/")[0]):
            continue

        rec = Record(
            source="docker",
            category="docker",
            item=f"{repo}:{tag}",
            current=tag,
            extra=f"ID:{img.get('ID','')[:12]}",
        )

        latest_tag = _docker_latest(repo)
        if latest_tag:
            rec.latest = latest_tag
            rec.status = cmp_ver(tag, latest_tag)
        records.append(rec)

    return records


def _docker_latest(repo: str) -> Optional[str]:
    """查 Docker Hub 的最新 semver tag
    借鉴 Watchtower: 用 v2 API, fallback v1"""
    api = f"library/{repo}" if "/" not in repo else repo

    # v2 API
    data = fetch(f"https://hub.docker.com/v2/repositories/{api}/tags/?page_size=50&ordering=last_updated")
    if data and "results" in data:
        vers = [t["name"] for t in data["results"] if re.match(r"^[\d.]+$", t.get("name", ""))]
        if vers:
            return max(vers, key=semver_sort_key)

    # v1 API fallback
    data = fetch(f"https://index.docker.io/v1/repositories/{api}/tags")
    if data and isinstance(data, list):
        vers = [d["name"] for d in data if re.match(r"^[\d.]+$", d.get("name", ""))]
        if vers:
            return max(vers, key=semver_sort_key)

    return None


