    cfg.setdefault("manual_apps", {})
    cfg["manual_apps"][name] = version
    save_config(cfg)
    print(f"  ✅ {name} = {version}")


def list_apps():
    cfg = load_config()
    apps = cfg.get("manual_apps", {})
    if not apps:
        print("  (空)")
        return
    print(f"  共 {len(apps)} 个:\n")
    for name, ver in apps.items():
        print(f"    📱 {name:<30} {ver}")


def scan_apps() -> List[Record]:
    """查 App Store / Play Store 最新版本
    借鉴多个开源 app-version-checker 的方案"""
    cfg = load_config()
    apps = cfg.get("manual_apps", {})
    if not apps:
        return []

    records: List[Record] = []
    for name, ver in apps.items():
        rec = Record(source="manual", category="app", item=name, current=ver or "?")
        latest = _appstore_latest(name)
        if latest:
            rec.latest = latest
            rec.status = cmp_ver(ver, latest)
        records.append(rec)
        icon = {"latest": "✅", "outdated": "🔄", "unknown": "❓"}.get(rec.status, "❓")
        print(f"    {icon} {name:<30} {ver}  →  {latest or '?'}")
    return records


def _appstore_latest(name: str) -> Optional[str]:
    """App Store (iTunes API) → 最可靠"""
    data = fetch(f"https://itunes.apple.com/search?term={urllib.parse.quote(name)}&limit=3&entity=software")
    if data and data.get("results"):
        return data["results"][0].get("version")

    # 如果名字是包名格式 (com.example.app), 查 Google Play
    if "." in name and name.count(".") >= 2:
        html_text = _fetch_text(f"https://play.google.com/store/apps/details?id={urllib.parse.quote(name)}")
        if html_text:
            m = re.search(r'\[\[\["([\d.]+)"\]\]', html_text)
            if m:
                return m.group(1)

    return None


def _fetch_text(url: str, timeout: int = 15) -> Optional[str]:
    try:
        req = urllib.request.Request(url, headers={
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
        })
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.read().decode("utf-8", errors="replace")
    except Exception:
        return None


