def run_scan(args):
    cfg = load_config()
    db = get_db()
    all_records: List[Record] = []

    # 1. 依赖
    dirs_to_scan = []
    if args.dir:
        p = Path(args.dir).expanduser().resolve()
        if p.is_dir():
            dirs_to_scan.append(p)
    else:
        for pcfg in cfg.get("projects", []):
            p = Path(pcfg["path"]).expanduser().resolve()
            if p.is_dir():
                dirs_to_scan.append(p)

    if dirs_to_scan:
        print(f"\n  ── 📦 依赖检查 ──")
        for p in dirs_to_scan:
            print(f"\n  📁 {p.name} ({p})")
            recs = scan_deps(p)
            all_records += recs
            print(f"  → {len(recs)} 个过时依赖")
            save_records(db, recs)

    # 2. Docker
    if cfg.get("docker_enabled", True):
        print(f"\n  ── 🐳 Docker 检查 ──\n")
        recs = scan_docker()
        all_records += recs
        print(f"  → {len(recs)} 个镜像")
        save_records(db, recs)

    # 3. App
    print(f"\n  ── 📱 App 检查 ──\n")
    recs = scan_apps()
    all_records += recs
    print(f"  → {len(recs)} 个 App")
    save_records(db, recs)

    db.close()

    # 汇总
    n_out = sum(1 for r in all_records if r.status == "outdated")
    n_ok = sum(1 for r in all_records if r.status == "latest")
    print(f"\n  {'=' * 45}")
    print(f"  总计: {len(all_records)}  |  🔄 {n_out} 可更新  |  ✅ {n_ok} 已最新")

    if args.report:
        rp = report(all_records)
        if args.open:
            try:
                import webbrowser
                webbrowser.open(f"file://{rp}")
                print("  🌐 已打开浏览器")
            except Exception:
                pass


def show_history(days: int = 7):
    db = get_db()
    cutoff = (datetime.datetime.now() - datetime.timedelta(days=days)).isoformat()
    rows = db.execute(
        "SELECT scanned_at,category,item_name,current_ver,latest_ver,status FROM history WHERE scanned_at >= ? ORDER BY scanned_at DESC LIMIT 80",
        (cutoff,),
    ).fetchall()
    db.close()
    if not rows:
        print(f"  📭 最近 {days} 天无记录")
        return

    grp: Dict[str, List] = {}
    for r in rows:
        grp.setdefault(r[0], []).append(r)

    print(f"\n  📋 最近 {days} 天 ({len(rows)} 条):\n")
    for st in sorted(grp.keys(), reverse=True)[:5]:
        items = grp[st]
        o = sum(1 for r in items if r[5] == "outdated")
        dt = datetime.datetime.fromisoformat(st)
        print(f"  [{dt.strftime('%m-%d %H:%M')}]  {len(items)} 条  |  {o} 个可更新")
        for r in items[:6]:
            ic = {"outdated": "🔄", "latest": "✅", "unknown": "❓"}.get(r[5], "❓")
            print(f"    {ic} {r[1]}:{r[2]}  {r[3]} → {r[4] or '?'}")
        if len(items) > 6:
            print(f"    ... 还有 {len(items)-6} 条")
        print()


