def find_projects(root: Path, max_depth: int = 3) -> List[Path]:
    """从 root 向下搜索所有含 manifest 文件的项目目录 (最多 max_depth 层)"""
    found: List[Path] = []
    root = root.resolve()
    # 先检查 root 本身
    if any((root / m).exists() for m in MANIFESTS):
        found.append(root)
        return found  # 本身就是项目, 不递归子目录
    # 否则扫描子目录
    if root.is_dir():
        try:
            for entry in root.iterdir():
                if entry.name.startswith(".") or entry.name.startswith("_"):
                    continue
                if entry.is_dir():
                    if any((entry / m).exists() for m in MANIFESTS):
                        found.append(entry)
                    elif max_depth > 1:
                        found += find_projects(entry, max_depth - 1)
        except PermissionError:
            pass
    return found


