# 跳过目录 (全小写匹配)
SKIP_DIRS = {
    "node_modules", ".git", ".svn", ".hg", "__pycache__", ".venv", "venv",
    "env", ".tox", "build", "dist", "target", "bin", "obj",
    "appdata", "cache", ".cache", ".npm", ".cargo", ".rustup",
    "program files", "program files (x86)", "windows", "winnt",
    "system32", "syswow64", "$recycle.bin", "system volume information",
    "perflogs", "recovery", ".vscode", ".idea", ".vs",
    "common files", "internet explorer", "microsoft.net",
    "assembly", "msbuild", "nuget",
}

def _should_skip(name: str) -> bool:
    return name.startswith(".") or name.lower() in SKIP_DIRS or name.startswith("$")

def find_projects(root: Path, max_depth: int = 4) -> List[Path]:
    """从 root 向下搜索所有含 manifest 的项目目录"""
    found: List[Path] = []
    try:
        root = root.resolve()
        if not root.is_dir():
            return found
        # 检查 root
        if any((root / m).exists() for m in MANIFESTS):
            found.append(root)
            return found
        # 扫描子目录
        if max_depth <= 0:
            return found
        try:
            for entry in sorted(root.iterdir(), key=lambda x: x.name):
                if _should_skip(entry.name):
                    continue
                if entry.is_dir():
                    if any((entry / m).exists() for m in MANIFESTS):
                        found.append(entry)
                    elif max_depth > 1:
                        found += find_projects(entry, max_depth - 1)
        except (PermissionError, OSError):
            pass
    except (PermissionError, OSError):
        pass
    return found


def find_projects_wide() -> List[Path]:
    """扫描整个用户目录找项目, 覆盖常用位置"""
    home = Path.home()  # C:\Users\27063
    candidates = [home]

    # 也扫桌面/文档/下载等常见位置
    for sub in ("Desktop", "Documents", "Downloads", "source", "sourcecode",
                "repos", "projects", "code", "github", "workspace"):
        p = home / sub
        if p.is_dir():
            candidates.append(p)

    all_projects: List[Path] = []
    seen: set = set()
    for root in candidates:
        for p in find_projects(root, max_depth=4):
            resolved = p.resolve()
            if str(resolved) not in seen:
                seen.add(str(resolved))
                all_projects.append(resolved)
    return all_projects"}

